const strip = (s = '') => s.replace(/<[^>]+>/g, '');
const anchorsHit = (e) => {
	const hay = lists(e).flat().map((b) => strip(textOf(b))).join('\n');
	return new Set((e.images ?? []).filter((im) => im.at && hay.includes(strip(im.at))).map((im) => im.id));
};

const report = { changed: 0, already: 0, problems: [] };
editStory((story) => {
	const flat = story.flatMap((c) => c.entries);
	for (const [n, edits] of Object.entries(EDITS)) {
		const e = flat[n - 1];
		if (e?.title !== TITLES[n]) {
			report.problems.push(`#${n}: expected “${TITLES[n]}”, found “${e?.title}”`);
			continue;
		}
		const before = anchorsHit(e);
		const dialogues = lists(e).flat().filter((b) => b.kind === 'dialogue');
		for (const [oldKo, newKo, enFrom, enTo] of edits) {
			const find = (ko) => dialogues.flatMap((b) => b.lines.map((l, i) => (l === ko ? { b, i } : null)).filter(Boolean));
			const hits = find(oldKo);
			const done = newKo ? find(newKo) : [];
			const target = hits.length === 1 ? hits[0] : hits.length === 0 && done.length === 1 ? done[0] : null;
			if (!target) {
				report.problems.push(`#${n}: ${hits.length} matches for “${oldKo}”`);
				continue;
			}
			const { b, i } = target;
			const enDone = !enFrom || (b.en[i].includes(enTo) && !b.en[i].includes(enFrom));
			if (!enDone && !b.en[i].includes(enFrom)) {
				report.problems.push(`#${n}: English “${enFrom}” not in “${b.en[i]}”`);
				continue;
			}
			if (enDone && (!newKo || b.lines[i] === newKo)) {
				report.already++;
				continue;
			}
			if (!enDone) b.en[i] = b.en[i].replace(enFrom, enTo);
			if (newKo) b.lines[i] = newKo;
			report.changed++;
		}
		const after = anchorsHit(e);
		const lost = [...before].filter((id) => !after.has(id));
		if (lost.length) report.problems.push(`#${n}: anchors lost ${lost.join(', ')}`);
	}
	if (report.problems.length) return false;
});

console.log(`changed ${report.changed}, already ${report.already}`);
if (report.problems.length) {
	console.log('NOT SAVED:\n' + report.problems.join('\n'));
	process.exitCode = 1;
}
